# NODE 2 -- Compliance audio

def audio_content_node(state: VideoAuditState)->Dict[str, Any]:
    '''
    Performs RetrievalAugment Generation to audit the content -  brand video
    '''
    
    logger.info("---[NODE -- AUDITOR] querying knowledge base & llm")
    transcript = state.get("transcript", "")
    if not transcript:
        logger.warning("No transcript avalable,skipping audit.....")
        return{
			"final_status" : "FAIL",
            "final_report" : "Audit skipped because video processing failed (No Transcript. )"
		}    
    
    # initialize clients    
    llm =  AzureChatOpenAI(
		azure_deployment=os.getenv("AZURE_OPENAI_CHAT_DEPLOYMENT"),
        openai_api_version  =  os.getenv("AZURE_OPENAI_API_VERSION"),
        temperature = 0.0
	)    
    structured_llm = llm.with_structured_output(ComplianceAudit)
    embeddings =  AzureOpenAIEmbeddings(
		azure_deployment = os.getenv("AZURE_OPENAI_EMBEDDING_DEPLOYMENT"),
        openai_api_version =  os.getenv("AZURE_OPENAI_API_VERSION")	)
    
    vector_Store = AzureSearch(
		azure_search_endpoint=os.getenv("AZURE_SEARCH_ENDPOINT"),
        azure_search_key  = os.getenv("AZURE_SEARCH_API_KEY"),
        index_name  =  os.getenv("AZURE_SEARCH_INDEX_NAME"),
        embedding_function = embeddings.embed_query     
	)
    #RAG Retrival
    
    ocr_text =  state.get("ocr_text", [])
    text_Segments =   state.get("transcript_segments", [])
    query_text  =  f"{transcript}  {''.join(ocr_text)}"
    docs =  vector_Store.similarity_search(query_text, k  = 3)
    retrieved_rules= "\n\n".join([doc.page_content for doc in docs])
    print("DOCS ",docs)
    
    system_prompt = f"""
You are a strict Senior Brand Compliance Auditor.

Your task is to audit the brand video against the OFFICIAL REGULATORY RULES
provided below.

========================
OFFICIAL REGULATORY RULES
========================

{retrieved_rules}

========================
INSTRUCTIONS
========================
1. Analyze BOTH:
   - The video transcript (spoken/audio content)
   - The on-screen OCR text (visual content)
 
2. Identify any compliance violations by comparing the video content
   against the OFFICIAL REGULATORY RULES.

3. For every violation, identify the exact evidence from the video
   that caused the violation.

4. For every violation, provide:
   - category
   - severity
   - evidence type
   - exact evidence
   - start time
   - end time
   - explanation of why it violates the rule

5. Use the timestamps provided with the transcript/OCR evidence.
   DO NOT invent timestamps.

6. The timestamp must represent the portion of the video where the
   violation occurs.

7. Set "evidence_type" to:
   - "AUDIO" if the violation comes from spoken content.
   - "OCR" if the violation comes from on-screen text.
   - "AUDIO_AND_OCR" if both contribute to the violation.

8. Only report a violation when it is supported by the
   OFFICIAL REGULATORY RULES.

11. If multiple violations occur at different timestamps, report
    them as separate compliance_results.

12. Severity must be one of:
    - CRITICAL
    - HIGH
    - MEDIUM
    - LOW

13. If no violations are found:
    - status = "PASS"
    - compliance_results = []

14. If one or more violations are found:
    - status = "FAIL"

15. final_report should provide a concise summary of the findings.

========================
IMPORTANT REASONING
========================

Follow this process:

VIDEO EVIDENCE
      ↓
Identify claim/content
      ↓
Compare against OFFICIAL REGULATORY RULES
      ↓
Determine whether it violates a rule
      ↓
Return violation + evidence + timestamp

Do NOT treat the transcript or OCR itself as a regulatory rule.

"""

    
    user_message = f"""
                 VIDEO_METADATA : {state.get('video_metadata', {})}
                 TRANSCRIPT : {transcript}
                 TRANSCRIPT SEGMENT = {text_Segments}
                 ON-SCREEN TEXT (OCR) : {ocr_text}                 
    """
    print("USER  msg :::\n", user_message)
    try:
        response = structured_llm.invoke([
			SystemMessage(content =  system_prompt),
            HumanMessage(content =  user_message)
		])
        
        print("response  :",response)
        print("\nresponse status :",response.status)
        print("response result  :",response.compliance_results)
        
    
        # Return EVERYTHING from the LLM
        return {
            "audit_response": response.model_dump()
        }
    except Exception as e:
        logger.error(f"System Error in Auditor Node : {str(e)}")        
        logger.error(f"Raw LLM response : {response.content if 'response' in locals() else 'None'}")
        return {
			"errors" : [str(e)],
            "final_status" : "FAIL"
		}